<script setup>
import { onMounted, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { useRefresh } from '../../composables/useRefresh.js';
import api, { messageOf } from '../../api/request.js';
const originalStatus=ref('draft'),historyDialog=ref(false),revisionDetail=ref(null);
async function showHistory(n){try{revisionDetail.value=(await api.get('/notices/'+n.id)).data;historyDialog.value=true;}catch(e){ElMessage.error(messageOf(e));}}
const props=defineProps({courseId:{type:[String,Number],required:true},readonly:Boolean});const notices=ref([]),dialog=ref(false),readersDialog=ref(false),readers=ref([]),editId=ref(null),form=ref({title:'',content:'',pinned:false,status:'draft',scheduled_at:''});
async function load(){try{notices.value=(await api.get(`/courses/${props.courseId}/notices`)).data}catch(e){ElMessage.error(messageOf(e))}}
function open(n){originalStatus.value=n?.status||'draft';editId.value=n?.id||null;form.value=n?{title:n.title,content:n.content,pinned:Boolean(n.pinned),status:n.status==='scheduled'?'scheduled':n.status==='published'?'published':'draft',scheduled_at:n.scheduled_at||''}:{title:'',content:'',pinned:false,status:'draft',scheduled_at:''};dialog.value=true}
async function save(){if(!form.value.title.trim())return ElMessage.warning('请填写通知标题');try{if(editId.value)await api.put(`/notices/${editId.value}`,form.value);else await api.post(`/courses/${props.courseId}/notices`,form.value);dialog.value=false;ElMessage.success('通知已保存');load()}catch(e){ElMessage.error(messageOf(e))}}
async function withdraw(n){try{const {value}=await ElMessageBox.prompt('撤回后学生只能看到撤回提示，历史保留。可填写撤回原因：','撤回通知',{inputType:'textarea'});await api.post(`/notices/${n.id}/withdraw`,{reason:value||''});ElMessage.success('通知已撤回');load()}catch(e){if(e!=='cancel')ElMessage.error(messageOf(e))}}
async function remove(n){try{await ElMessageBox.confirm('确定删除这条未发布通知？','确认',{type:'warning'});await api.delete(`/notices/${n.id}`);load()}catch(e){if(e!=='cancel')ElMessage.error(messageOf(e))}}
async function showReaders(n){try{readers.value=(await api.get(`/notices/${n.id}/readers`)).data;readersDialog.value=true}catch(e){ElMessage.error(messageOf(e))}}
useRefresh(load);
</script>
<template><div><div class="toolbar"><el-button type="primary" color="#15554e" :disabled="readonly" @click="open()">发布通知</el-button><span class="hint">已发布通知可修正或撤回，不能回到草稿。</span></div><div v-if="notices.length"><article v-for="n in notices" :key="n.id" class="assignment-card"><div style="display:flex;justify-content:space-between;gap:20px"><div><span class="badge">{{({draft:'草稿',scheduled:'定时发布',published:'已发布',withdrawn:'已撤回'})[n.status]}}</span><span v-if="n.pinned" class="badge" style="background:#e6a23c">置顶</span><h3>{{n.title}}</h3><p style="white-space:pre-wrap;line-height:1.8;color:#566e69">{{n.content}}</p><span class="hint">计划 {{n.scheduled_at||'—'}} · 实际发布 {{n.published_at||'—'}} · 修改 {{n.updated_at}} · 撤回 {{n.withdrawn_at||'—'}} · 已读 {{n.read_count||0}} 人 · 修订 {{n.content_revision}}</span></div><div class="assignment-actions"><el-button @click="showHistory(n)">历史</el-button><el-button @click="showReaders(n)">已读名单</el-button><el-button v-if="n.status!=='withdrawn'" :disabled="readonly" @click="open(n)">编辑</el-button><el-button v-if="n.status==='published'" type="warning" :disabled="readonly" @click="withdraw(n)">撤回</el-button><el-button v-if="n.status==='draft'" type="danger" text :disabled="readonly" @click="remove(n)">删除</el-button></div></div></article></div><div v-else class="empty">还没有通知。</div><el-dialog v-model="dialog" :title="editId?'编辑通知':'发布通知'" width="min(560px,92vw)"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="内容"><el-input v-model="form.content" type="textarea" :rows="6"/></el-form-item><el-form-item v-if="originalStatus!=='published'" label="发布方式"><el-radio-group v-model="form.status"><el-radio value="draft">草稿</el-radio><el-radio value="published">立即发布</el-radio><el-radio value="scheduled">定时发布</el-radio></el-radio-group></el-form-item><el-form-item v-if="form.status==='scheduled'" label="发布时间"><el-date-picker v-model="form.scheduled_at" type="datetime" value-format="YYYY-MM-DD HH:mm:ss"/></el-form-item><el-checkbox v-model="form.pinned">置顶显示</el-checkbox></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" color="#15554e" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="readersDialog" title="已读学生" width="min(520px,92vw)"><el-table :data="readers"><el-table-column prop="username" label="学号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="first_read_at" label="首次查看"/><el-table-column prop="last_read_at" label="最近查看"/><el-table-column prop="last_seen_revision" label="已读版本"/></el-table></el-dialog><el-dialog v-model="historyDialog" title="通知历史" width="min(760px,94vw)"><template v-if="revisionDetail"><p>首次发布：{{revisionDetail.published_at||'未发布'}} · 撤回：{{revisionDetail.withdrawn_at||'—'}}</p><p v-if="revisionDetail.withdrawn_reason">撤回原因：{{revisionDetail.withdrawn_reason}}</p><article v-for="r in revisionDetail.revisions" :key="r.revision" class="assignment-card"><b>版本{{r.revision}} · {{r.changed_at}} · {{r.title}}</b><p style="white-space:pre-wrap">{{r.content}}</p></article></template></el-dialog></div></template>
